    private void Start()
    {
        GameEventsManager.SafeAddListener(OnGameEvent);
        StartCoroutine(GetEventDataRoutine(true));
    }

    public IEnumerator GetEventDataRoutine(bool isFirstGet)
    {
        if (LevelManager.Instance.GetCurrentLevelNumber() < MINIMUM_LEVEL_REQUIREMENT) yield break;

        IsLoadingData = true;
        ErrorOnDataLoading = false;
        _retryCount = 0;

        yield return new WaitUntil(() => GameDataStore.Instance.LoginRequestData != null);

        int tries = 0;
        while (true)
        {
            if (tries > 3) break;
            tries++;
            var allTimeRequest = LeaderboardRequest.GetAllTimeRequest();
            var weeklyRequest = LeaderboardRequest.GetWeeklyRequest();
            var weeklyStatus = LeaderboardRequest.GetWeeklyStatus(); 

             yield return ServerRequester.Instance.BasicRequest(allTimeRequest, ServerRequester.RequestCode.GetLeaderboard,  (GetAllTimeLeaderboardResponse response) => OnAllTimeSucess(response), OnError);  
             yield return ServerRequester.Instance.BasicRequest(weeklyRequest, ServerRequester.RequestCode.GetLeaderboard,  (GetAllTimeLeaderboardResponse response) => OnWeeklySuccess(response), OnError);

             yield return ServerRequester.Instance.BasicRequest(weeklyStatus, ServerRequester.RequestCode.GetLeaderboard,  (LeaderboardWeeklyStatusResponse response) => OnWeeklyStatusSuccess(response), OnError);


             // If we get here, all requests were successful
             if (!ErrorOnDataLoading){
                 if (Blob.EndDate < DateTime.UtcNow && isFirstGet) yield return HandleWeeklyEnd(false);
                 else if (isFirstGet) StartWeeklyCountdown();
                 break;
             }
             yield return null;
        }

        yield return null;
        IsLoadingData = false;
    }

    private void OnError(ServerError error)
    {
        Debug.LogError($"Leaderboard data loading error: {error.ErrorMessage}");
        ErrorOnDataLoading = true;
        IsLoadingData = false;  // Reset loading flag on error
    }

    private void OnWeeklyStatusSuccess(LeaderboardWeeklyStatusResponse rawData)
    {
        ErrorOnDataLoading = false;
        var leagues = rawData.Leagues.ToList();
        var weeklyStatus = leagues.FirstOrDefault(league => league.Name.StringToElo() == Blob.WeeklyElo);   
        if (weeklyStatus != null && weeklyStatus.Name != string.Empty) Blob.WeeklyStatus = weeklyStatus;
        if (leagues.Any(league => league.Status == "active")) Blob.State = LiveOpsEventState.Joined;
    }


    private void OnAllTimeSucess(GetAllTimeLeaderboardResponse rawData)
    {
        ErrorOnDataLoading = false;
        var data = rawData.Leaderboard;

        if (Blob == null)
        {
            Blob = new LeaderboardBlob()
            {
                AllTimeUsers = data.Users.ToList(),
            };
        }
        else
        {
            Blob.AllTimeUsers = data.Users.ToList();
        }

        bool hasFoundPlayer = false;
        for (int i = 0; i < Blob.AllTimeUsers.Count; i++)
        {
            var user = Blob.AllTimeUsers[i];
            if (user.IsPlayer && !hasFoundPlayer)
            {
                AllTimePlayerData = user;
                hasFoundPlayer = true;
                continue;
            }
            user.IsPlayer = false;
        }
    }


    private void OnWeeklySuccess(GetAllTimeLeaderboardResponse rawData)
    {
        ErrorOnDataLoading = false;
        var data = rawData.Leaderboard;
        if (Blob == null)
        {
            Blob = new LeaderboardBlob()
            {
                StartDate = DateTime.UtcNow,
                EndDate = data.WeeklyEndDate.ConvertUnixTimeToDateTime(),
                WeeklyUsers = data.Users.ToList(),
                WeeklyElo = data.Name.StringToElo()
            };
        }
        else
        {
            Blob.StartDate = DateTime.UtcNow;
            Blob.EndDate = data.WeeklyEndDate.ConvertUnixTimeToDateTime();
            Blob.WeeklyUsers = data.Users.ToList();
            Blob.WeeklyElo = data.Name.StringToElo();
        }
        bool hasFoundPlayer = false;
        for (int i = 0; i < Blob.WeeklyUsers.Count; i++)
        {
            var user = Blob.WeeklyUsers[i];
            if (user.IsPlayer && !hasFoundPlayer)
            {
                WeeklyPlayerData = user;
                hasFoundPlayer = true;
                continue;
            }
            user.IsPlayer = false;
        }
    }

    private void OnGameEvent(GameEvent gameEvent)
    {
        if (LevelManager.Instance.GetCurrentLevelNumber() < MINIMUM_LEVEL_REQUIREMENT) return;

        switch (gameEvent.GameEventType)
        {
            case GameEventType.LevelEnded:
                var endInfo = (gameEvent as LevelEnded).EndLevelInformation;
                if (!endInfo.Won) StartCoroutine(GetEventDataRoutine(false));
                break;
            case GameEventType.PlayerDataUpdated:
                StartCoroutine(GetEventDataRoutine(false));
                break;
        }
    }

    private void StartWeeklyCountdown()
    {
        PlayerPrefs.DeleteKey(WeeklyEndCallbackKey);
        TimeManager.Instance.Schedule(WeeklyEndCallbackKey, Blob.EndDate - DateTime.UtcNow, OnWeeklyEndCallback, deleteManually: true);
    }

    public IEnumerator JoinWeeklyLeague()
    {
        if (LevelManager.Instance.GetCurrentLevelNumber() < MINIMUM_LEVEL_REQUIREMENT) 
        {
            IsLoadingData = false;
            yield break;
        }

        IsLoadingData = true;
        HasBeenPromoted = false;
        var weeklyRequest = LeaderboardRequest.JoinNewWeeklyRequest();
        yield return ServerRequester.Instance.BasicRequest(weeklyRequest, ServerRequester.RequestCode.GetLeaderboard,  (GetAllTimeLeaderboardResponse response) => OnWeeklySuccess(response), OnError);

        StartWeeklyCountdown();

        if(LeaderboardMenu.Instance != null && LeaderboardMenu.Instance.gameObject.activeSelf) OnWeeklyTimerChanged?.Invoke();
        yield return null;
        IsLoadingData = false;
    } 

